import java.util.Scanner;
public class BmiCalculator1 {
	public static void main(String[] args) {
		//Khatwa 1: Istilam al-wazn wal-toul min al-mustakhdim
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil al-wazn bil-pounds:");
		double weight = scan.nextDouble();
		System.out.println("Adkhil al-toul bil-inches:");
		double height = scan.nextDouble();
		scan.close();
		//Khatwa 2: Ihsab al-BMI
		double bmi = weight / Math.pow(height, 2) * 703;	
		//Khatwa 3: Tabaa al-natija
		System.out.println("Al-BMI huwa: " + bmi);
	}
}
